window.THEORY_META=window.THEORY_META||{};Object.assign(window.THEORY_META,{"eotvos":{"abbr":"Eötvös","full":{"en":"Eötvös Physics Competition","ko":"Eötvös 물리 경시대회"},"officialWebsite":"https://eik.bme.hu/~vanko/fizika/eotvos.htm","omr":false,"plain":true,"resourceNote":{"en":"Includes the official 1949 reprint, verified complete historical sets from selected years in 1962–1970 and 1987–1991, and public materials for every year 1994–2026. Historical reprints, combined reports and standalone papers are distinguished; available English translations accompany Hungarian originals. Annual coverage since 1916 remains incomplete.","ko":"1949년 공식 재수록, 1962~1970년·1987~1991년 중 보고서에서 실제 문제 전체를 확인한 역사 자료, 1994~2026년 공개 자료를 모았습니다. 역사 재수록·문제와 해설 합본·독립 문제지를 구분하고 확보한 영문 번역을 함께 제공합니다. 1916년부터의 모든 연도를 확보한 것은 아닙니다."},"resources":[{"label":{"en":"Official recent papers","ko":"공식 최근 문제지"},"url":"https://eik.bme.hu/~vanko/fizika/eotvos.htm"},{"label":{"en":"Official historical archive","ko":"공식 역사 자료실"},"url":"https://elft.hu/versenyek/elft-szervezesu-fizikaversenyek/eotvos-lorand-fizikaverseny/eotvos-versenyek/"},{"label":{"en":"phoXiv papers and translations","ko":"phoXiv 기출·영문 번역"},"url":"https://phoxiv.org/olympiads/eotvos"},{"label":{"en":"2025 published solutions (HTML)","ko":"2025년 공식 해설 (HTML)"},"url":"https://www.komal.hu/oldal?lap=EotvosVerseny2025beszamolo"},{"label":{"en":"1991 problems and solutions (HTML)","ko":"1991년 문제·해설 원문 (HTML)"},"url":"https://fizikaiszemle.elft.hu/archivum/fsz9207/rgy9207.html"},{"label":{"en":"1969 problem 1 and solution (partial, HTML)","ko":"1969년 1번 문제·해설 (일부, HTML)"},"url":"https://fizikaiszemle.elft.hu/archivum/fsz0311/fiztan0311.html"}],"rounds":false,"scope":{"en":"National · Hungary","ko":"국가 · 헝가리"},"since":1916}});
